#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Banc d'essai des mods Claude Code : chaque mod est INSTALLÉ pour de vrai, mais seulement
# dans un projet jetable (scope project), testé dans une session Claude Code, puis soit
# gardé (réinstallé pour toi, scope user), soit désinstallé aussitôt.
#
# Usage : bash banc.sh                     tous les mods pas encore notés, dans l'ordre du classement
#         bash banc.sh top                 un seul palier : top, cible, non, lemo
#         bash banc.sh token-weather usage-band   des mods précis (nom ou clé, cf. mods.tsv)
#         bash banc.sh --refaire           recommence (l'ancien resultats.tsv passe en .bak)
#         bash banc.sh --nettoyer          retire ce que le banc a laissé (mod en cours, marketplaces ajoutées)
# Variables : CLAUDE_BIN (défaut : claude du PATH), BANC_MODELE (modèle des sessions de test, ex. claude-haiku-4-5-20251001).

ICI="$(cd "$(dirname "$0")" && pwd)"
CLAUDE="${CLAUDE_BIN:-claude}"
MODS="$ICI/mods.tsv"
RES="$ICI/resultats.tsv"
BAC="$ICI/bac-a-sable"
ETAT="$ICI/.banc"
ENCOURS="$ETAT/en-cours"            # plugin@marketplace installé en scope project, pas encore tranché
AJOUTEES="$ETAT/marketplaces"       # marketplaces ajoutées PAR le banc (seules celles-là seront retirées)
GARDES="$ETAT/gardes"               # plugin@marketplace gardés en scope user
SRC="${XDG_CACHE_HOME:-$HOME/.cache}/claude-mods-banc/sources"
mkdir -p "$ETAT"; touch "$AJOUTEES" "$GARDES"

# Annonce d'étape en français (la bibliothèque au-dessus reste intacte).
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Mod %s/%s · %s%s\n' "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}
titre() { printf '\033]0;%s\007' "$1"; }

cc() { "$CLAUDE" "$@"; }
# Liste des plugins vus depuis le bac (scope project compris) ; vide si rien.
# Installé dans le bac = activé dans SES réglages projet (plugin list mélangerait l'install user d'un mod gardé).
installe_dans_bac() { [[ -f "$BAC/.claude/settings.json" ]] && grep -qE "\"${1//./\\.}\" *: *true" "$BAC/.claude/settings.json"; }
marketplace_existe() { cc plugin marketplace list 2>/dev/null | grep -qE "❯ $1\$"; }

# ── Remise en ordre : ce que le banc a installé ou ajouté, et rien d'autre ──
desinstaller_en_cours() {
  [[ -s "$ENCOURS" ]] || return 0
  local p; p=$(cat "$ENCOURS")
  (cd "$BAC" && cc plugin uninstall "$p" --scope project >/dev/null 2>&1) || true
  (cd "$BAC" && cc plugin prune --scope project -y >/dev/null 2>&1) || true
  if installe_dans_bac "$p"; then warn "$p n'a pas pu être désinstallé du bac : cd $BAC && $CLAUDE plugin uninstall $p --scope project"
  else note "désinstallé : $p"; : >"$ENCOURS"; fi
}
retirer_marketplaces() {
  local m reste=()
  while IFS= read -r m; do
    [[ -z "$m" ]] && continue
    if grep -q "@$m\$" "$GARDES"; then reste+=("$m"); continue; fi   # un mod gardé en dépend
    cc plugin marketplace remove "$m" >/dev/null 2>&1 && note "marketplace retirée : $m" || reste+=("$m")
  done <"$AJOUTEES"
  printf '%s\n' "${reste[@]+"${reste[@]}"}" | grep . >"$AJOUTEES" || : >"$AJOUTEES"
}
nettoyer() { desinstaller_en_cours; retirer_marketplaces; titre "terminal"; }

case "${1:-}" in
  --nettoyer) nettoyer; printf 'Rien d’autre à retirer.\n'; exit 0 ;;
  --refaire) [[ -f "$RES" ]] && mv "$RES" "$RES.bak"; shift ;;
esac

command -v "$CLAUDE" >/dev/null 2>&1 || { printf '%s introuvable (CLAUDE_BIN pour un autre chemin)\n' "$CLAUDE"; exit 1; }
command -v git >/dev/null 2>&1 || { printf 'git introuvable\n'; exit 1; }
touch "$RES"

# Un arrêt brutal précédent a pu laisser un mod installé : on le retire avant tout.
[[ -s "$ENCOURS" ]] && { printf 'Un essai précédent n’a pas été tranché : '; desinstaller_en_cours; }
trap 'printf "\n"; nettoyer' EXIT

# Sélection : paliers et/ou noms en arguments, sinon tout.
FILTRES=("$@")
retenu() { # $1 cle $2 nom $3 palier
  (( ${#FILTRES[@]} )) || return 0
  local f; for f in "${FILTRES[@]}"; do [[ "$f" == "$1" || "$f" == "$2" || "$f" == "$3" ]] && return 0; done; return 1
}

RANGS=(); CLES=(); NOMS=(); PALIERS=(); DROITS=(); MKS=(); PLUGS=(); SOURCES=(); DEPOTS=(); SHAS=(); TESTS=(); ALERTES=(); TXTS=()
while IFS=$'\t' read -r rang cle nom palier droits mk plug source depot sha test alerte txt <&3; do
  [[ "$rang" == \#* ]] && continue
  retenu "$cle" "$nom" "$palier" || continue
  awk -F'\t' -v k="$cle" '$2==k{f=1} END{exit !f}' "$RES" && continue
  RANGS+=("$rang"); CLES+=("$cle"); NOMS+=("$nom"); PALIERS+=("$palier"); DROITS+=("$droits"); MKS+=("$mk"); PLUGS+=("$plug")
  SOURCES+=("$source"); DEPOTS+=("$depot"); SHAS+=("$sha"); TESTS+=("$test"); ALERTES+=("$alerte"); TXTS+=("$txt")
done 3<"$MODS"
TOTAL_STAGES=${#CLES[@]}

# Bac à sable : petit dépôt git jetable, pour que les gardes aient quelque chose à garder.
# Pas de README.md : certains réglages bloquent l'écriture de markdown, ce qui fausserait les tests.
prepare_bac() {
  [[ -d "$BAC/.git" ]] && return 0
  mkdir -p "$BAC/src" "$BAC/build"
  printf 'Bac à sable\n\nProjet factice pour tester des mods Claude Code.\n' >"$BAC/LISEZMOI.txt"
  printf 'export function add(a, b) {\n  return a + b;\n}\n' >"$BAC/src/math.js"
  printf 'import { add } from "./math.js";\nconsole.log(add(2, 3));\n' >"$BAC/src/app.js"
  for f in a b c; do printf 'console.log("%s");\n' "$f" >"$BAC/build/$f.js"; done
  printf 'Note sans importance, à supprimer pendant les tests.\n' >"$BAC/notes.txt"
  printf 'FAKE_API_KEY=sk-test-FAUX-0000000000000000\n' >"$BAC/.env"
  git -C "$BAC" init -q && git -C "$BAC" add -A && git -C "$BAC" -c user.name=banc -c user.email=banc@local commit -qm "état initial"
}
# Remet le bac à l'état initial ; .claude/ (où vit l'installation scope project) n'est pas touché.
reset_bac() { git -C "$BAC" reset -q --hard && git -C "$BAC" clean -qfdx -e .claude; }

# Clone local (marketplace en sous-dossier, ou mod sans plugin publié), au commit audité.
clone_audite() { # $1 depot $2 sha → chemin du clone
  local d="$SRC/${1/\//_}"
  if [[ ! -d "$d/.git" ]]; then mkdir -p "$SRC"; git clone -q "https://github.com/$1" "$d" || return 1; fi
  git -C "$d" fetch -q origin 2>/dev/null || true
  git -C "$d" checkout -q "$2" 2>/dev/null || return 1
  printf '%s' "$d"
}
assurer_marketplace() { # $1 nom $2 source
  marketplace_existe "$1" && return 0
  local cible
  case "$2" in
    github:*) cible="${2#github:}" ;;
    clone:*) local r="${2#clone:}"; local d; d=$(clone_audite "${r%%:*}" "$3") || return 1; cible="$d/${r#*:}" ;;
  esac
  note "ajout de la marketplace $1 ($cible)"
  cc plugin marketplace add "$cible" >/dev/null 2>&1 || return 1
  echo "$1" >>"$AJOUTEES"
}
# Le code a-t-il bougé depuis l'audit ?
verifier_commit() { # $1 depot $2 sha
  local h; h=$(git ls-remote "https://github.com/$1" HEAD 2>/dev/null | cut -f1)
  [[ -z "$h" ]] && { note "commit actuel du dépôt non vérifiable (réseau ?)"; return; }
  [[ "$h" == "$2" ]] && note "code identique au commit audité (${2:0:7})" \
    || warn "le dépôt a changé depuis l'audit (${2:0:7} → ${h:0:7}) : ce qui sera installé n'a pas été relu"
}

_clear
printf '\n%s%s  Banc d’essai des mods Claude Code%s\n\n' "$BOLD" "$BLUE" "$RESET"
say "$TOTAL_STAGES mod(s) à essayer, $(grep -c . "$RES" || true) déjà noté(s) dans resultats.tsv."
say "Pour chaque mod : je montre ce qu'il fait et comment le déclencher, je l'installe"
say "UNIQUEMENT dans le projet jetable bac-a-sable/, puis j'ouvre Claude Code dedans."
say "Quitte Claude (/exit) quand tu as vu, puis tranche : garder (installé pour toi)"
say "ou non (désinstallé aussitôt). Ctrl-C à tout moment : le mod en cours est retiré."
warn "Un mod tourne avec TES droits, sans sandbox. Lis sa fiche et son code avant d'accepter."
note "Rien n'est poussé, rien n'est écrit hors du bac, sauf la liste des marketplaces de Claude Code."
(( TOTAL_STAGES )) || { printf '\n'; say "Rien à faire : tout est déjà noté. --refaire pour recommencer."; exit 0; }
pause "Entrée pour commencer"
prepare_bac

VUS=0
for i in "${!CLES[@]}"; do
  reset_bac
  nom="${NOMS[$i]}"; id="${PLUGS[$i]}@${MKS[$i]}"
  stage "#${RANGS[$i]} $nom"
  note "palier ${PALIERS[$i]} · droits : ${DROITS[$i]} · https://github.com/${DEPOTS[$i]}"
  verifier_commit "${DEPOTS[$i]}" "${SHAS[$i]}"
  printf '\n'; say "${TXTS[$i]}"
  printf '\n  %sComment le tester%s\n' "$BOLD" "$RESET"
  say "${TESTS[$i]}"
  [[ "${ALERTES[$i]}" != "-" ]] && { printf '\n'; warn "${ALERTES[$i]}"; }
  printf '\n  %s[Entrée] installer et tester · p passer · q quitter%s ' "$DIM" "$RESET"
  read -r choix || true
  case "$choix" in
    q | Q) break ;;
    p | P) printf '%s\t%s\tpassé\t-\t-\t%s\n' "${RANGS[$i]}" "${CLES[$i]}" "$(date +%F)" >>"$RES"; continue ;;
  esac

  args=()
  if [[ "${SOURCES[$i]}" == dir:* ]]; then
    # Pas de plugin publié : chargé pour une session seulement, rien à installer ni désinstaller.
    r="${SOURCES[$i]#dir:}"
    d=$(clone_audite "${r%%:*}" "${SHAS[$i]}") || { warn "clone impossible"; pause; continue; }
    args=(--plugin-dir "$d/${r#*:}")
    note "pas de plugin publié : chargé avec --plugin-dir pour cette session"
  else
    assurer_marketplace "${MKS[$i]}" "${SOURCES[$i]}" "${SHAS[$i]}" || { warn "marketplace ${MKS[$i]} injoignable"; pause; continue; }
    echo "$id" >"$ENCOURS"
    say "Installation de $id dans le bac (scope project) :"
    if ! (cd "$BAC" && cc plugin install "$id" --scope project); then
      warn "installation refusée ou échouée"; desinstaller_en_cours
      printf '%s\t%s\tcassé\tinstallation échouée\t-\t%s\n' "${RANGS[$i]}" "${CLES[$i]}" "$(date +%F)" >>"$RES"; pause; continue
    fi
  fi

  titre "MOD À TESTER : $nom"
  [[ -n "${BANC_MODELE:-}" ]] && args+=(--model "$BANC_MODELE")
  (cd "$BAC" && cc "${args[@]+"${args[@]}"}") || warn "Claude Code s'est terminé avec une erreur."
  titre "banc d’essai"

  _clear
  printf '\n%s%s  Verdict · %s%s\n\n' "$BOLD" "$BLUE" "$nom" "$RESET"
  say "1 garder (installé pour toi, dans tous tes projets)"
  say "2 bof · 3 non merci · 4 n'a pas marché   (2, 3 et 4 désinstallent)"
  say "Entrée = passer (désinstallé aussi)"
  printf '  %s? %s' "$YELLOW" "$RESET"; read -r v || true
  case "$v" in 1) verdict="garder" ;; 2) verdict="bof" ;; 3) verdict="non" ;; 4) verdict="cassé" ;; *) verdict="passé" ;; esac
  printf '  %sUne note (facultatif) :%s ' "$BOLD" "$RESET"; read -r n || true
  n="${n//$'\t'/ }"

  action="-"
  if [[ "${SOURCES[$i]}" == dir:* ]]; then
    [[ "$verdict" == garder ]] && note "modèle à copier : https://github.com/${DEPOTS[$i]}" && action="à copier"
  elif [[ "$verdict" == garder ]]; then
    if (cd "$HOME" && cc plugin install "$id" --scope user); then
      echo "$id" >>"$GARDES"; action="installé (user)"
      printf '  %s✓ installé pour toi%s · désinstaller plus tard : %s plugin uninstall %s\n' "$GREEN" "$RESET" "$CLAUDE" "$id"
    else
      warn "installation user échouée : le mod reste à réinstaller à la main"; action="échec install user"
    fi
    desinstaller_en_cours
  else
    desinstaller_en_cours; action="désinstallé"
  fi
  printf '%s\t%s\t%s\t%s\t%s\t%s\n' "${RANGS[$i]}" "${CLES[$i]}" "$verdict" "${n:--}" "$action" "$(date +%F)" >>"$RES"
  printf '  %s✓ noté%s %s → resultats.tsv\n' "$GREEN" "$RESET" "$verdict"
  VUS=$((VUS + 1)); sleep 1
done

_clear
printf '\n%s%s  ✓ Session terminée%s\n\n' "$BOLD" "$GREEN" "$RESET"
say "$VUS mod(s) testé(s) cette fois, $(grep -c . "$RES" || true) noté(s) au total."
for k in garder bof non cassé passé; do
  c=$(awk -F'\t' -v k="$k" '$3==k' "$RES" | wc -l | tr -d ' ')
  (( c )) && note "$k : $c"
done
[[ -s "$GARDES" ]] && { printf '\n'; say "Installés pour toi : $(tr '\n' ' ' <"$GARDES")"; }
printf '\n'
